// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, OperationSide, TransposeOperation } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates whether the operation completed successfully. A value of `0` indicates success.
*/
type StatusCode = number;

/**
* Interface describing `dormbr`.
*/
interface Routine {
	/**
	* Multiplies a general matrix by the orthogonal matrix from a bi-diagonal reduction determined by `DGEBRD`.
	*
	* ## Notes
	*
	* -   `Q` and `P^T` are the orthogonal matrices determined by `DGEBRD` when reducing a real matrix `A` to bi-diagonal form, `A = Q * B * P^T`.
	*
	* -   If VECT = 'Q', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
	*
	*     -   `Q * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
	*     -   `Q^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
	*     -   `C * Q`  if SIDE = 'right' and TRANS = 'no-transpose', or
	*     -   `C * Q^T`  if SIDE = 'right' and TRANS = 'transpose'.
	*
	* -   If VECT = 'P', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
	*
	*     -   `P * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
	*     -   `P^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
	*     -   `C * P`  if SIDE = 'right' and TRANS = 'no-transpose', or
	*     -   `C * P^T`  if SIDE = 'right' and TRANS = 'transpose'.
	*
	* -   If SIDE = 'left', `LWORK >= max(1,N)`.
	*
	* -   If SIDE = 'right', `LWORK >= max(1,M)`.
	*
	* @param order - storage layout
	* @param vect - specifies whether the matrix `Q` or the matrix `P` is applied
	* @param side - specifies the side of multiplication with `C`
	* @param trans - `'no-transpose'` for `Q` or `P`, `'transpose'` for `Q^T` or `P^T`
	* @param M - number of rows of `C`
	* @param N - number of columns of `C`
	* @param K - number of elementary reflectors
	* @param A - reflector vectors from `DGEBRD`
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param TAU - scalar factors of elementary reflectors
	* @param C - input/output matrix
	* @param LDC - stride of the first dimension of `C` (a.k.a., leading dimension of the matrix `C`)
	* @param WORK - workspace array
	* @param LWORK - dimension of the array `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1, 0, 0 ] );
	* var TAU = new Float64Array( [ 2 ] );
	* var C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
	* var WORK = new Float64Array( 3 );
	*
	* var info = dormbr( 'row-major', 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 );
	* // returns 0
	* // C => <Float64Array>[ -1, -3, -5, 2, 4, 6 ]
	*/
	( order: Layout, vect: 'Q' | 'P', side: OperationSide, trans: TransposeOperation, M: number, N: number, K: number, A: Float64Array, LDA: number, TAU: Float64Array, C: Float64Array, LDC: number, WORK: Float64Array, LWORK: number ): StatusCode;

	/**
	* Multiplies a general matrix by the orthogonal matrix from a bi-diagonal reduction determined by `DGEBRD` using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   `Q` and `P^T` are the orthogonal matrices determined by `DGEBRD` when reducing a real matrix `A` to bi-diagonal form, `A = Q * B * P^T`.
	*
	* -   If VECT = 'Q', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
	*
	*     -   `Q * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
	*     -   `Q^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
	*     -   `C * Q`  if SIDE = 'right' and TRANS = 'no-transpose', or
	*     -   `C * Q^T`  if SIDE = 'right' and TRANS = 'transpose'.
	*
	* -   If VECT = 'P', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
	*
	*     -   `P * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
	*     -   `P^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
	*     -   `C * P`  if SIDE = 'right' and TRANS = 'no-transpose', or
	*     -   `C * P^T`  if SIDE = 'right' and TRANS = 'transpose'.
	*
	* -   If SIDE = 'left', `LWORK >= max(1,N)`.
	*
	* -   If SIDE = 'right', `LWORK >= max(1,M)`.
	*
	* @param vect - specifies whether the matrix `Q` or the matrix `P` is applied
	* @param side - specifies the side of multiplication with `C`
	* @param trans - `'no-transpose'` for `Q` or `P`, `'transpose'` for `Q^T` or `P^T`
	* @param M - number of rows of `C`
	* @param N - number of columns of `C`
	* @param K - number of elementary reflectors
	* @param A - reflector vectors from `DGEBRD`
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param TAU - scalar factors of elementary reflectors
	* @param strideTAU - stride for `TAU`
	* @param offsetTAU - starting index for `TAU`
	* @param C - input/output matrix
	* @param strideC1 - stride of the first dimension of `C`
	* @param strideC2 - stride of the second dimension of `C`
	* @param offsetC - starting index for `C`
	* @param WORK - workspace array
	* @param strideWORK - stride for `WORK`
	* @param offsetWORK - starting index for `WORK`
	* @param LWORK - dimension of the array `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1, 0, 0 ] );
	* var TAU = new Float64Array( [ 2 ] );
	* var C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
	* var WORK = new Float64Array( 3 );
	*
	* var info = dormbr.ndarray( 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, 1, 0, TAU, 1, 0, C, 3, 1, 0, WORK, 1, 0, 3 );
	* // returns 0
	* // C => <Float64Array>[ -1, -3, -5, 2, 4, 6 ]
	*/
	ndarray( vect: 'Q' | 'P', side: OperationSide, trans: TransposeOperation, M: number, N: number, K: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, TAU: Float64Array, strideTAU: number, offsetTAU: number, C: Float64Array, strideC1: number, strideC2: number, offsetC: number, WORK: Float64Array, strideWORK: number, offsetWORK: number, LWORK: number ): StatusCode;
}

/**
* Multiplies a general matrix by the orthogonal matrix from a bi-diagonal reduction determined by `DGEBRD`.
*
* ## Notes
*
* -   `Q` and `P^T` are the orthogonal matrices determined by `DGEBRD` when reducing a real matrix `A` to bi-diagonal form, `A = Q * B * P^T`.
*
* -   If VECT = 'Q', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
*
*     -   `Q * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
*     -   `Q^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
*     -   `C * Q`  if SIDE = 'right' and TRANS = 'no-transpose', or
*     -   `C * Q^T`  if SIDE = 'right' and TRANS = 'transpose'.
*
* -   If VECT = 'P', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
*
*     -   `P * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
*     -   `P^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
*     -   `C * P`  if SIDE = 'right' and TRANS = 'no-transpose', or
*     -   `C * P^T`  if SIDE = 'right' and TRANS = 'transpose'.
*
* @param order - storage layout
* @param vect - specifies whether the matrix `Q` or the matrix `P` is applied
* @param side - specifies the side of multiplication with `C`
* @param trans - `'no-transpose'` for `Q` or `P`, `'transpose'` for `Q^T` or `P^T`
* @param M - number of rows of `C`
* @param N - number of columns of `C`
* @param K - number of elementary reflectors
* @param A - reflector vectors from `DGEBRD`
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param TAU - scalar factors of elementary reflectors
* @param C - input/output matrix
* @param LDC - stride of the first dimension of `C` (a.k.a., leading dimension of the matrix `C`)
* @param WORK - workspace array
* @param LWORK - dimension of the array `WORK`
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 0, 0 ] );
* var TAU = new Float64Array( [ 2 ] );
* var C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
* var WORK = new Float64Array( 3 );
*
* var info = dormbr( 'row-major', 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 );
* // returns 0
* // C => <Float64Array>[ -1, -3, -5, 2, 4, 6 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 0, 0 ] );
* var TAU = new Float64Array( [ 2 ] );
* var C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
* var WORK = new Float64Array( 3 );
*
* var info = dormbr.ndarray( 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, 1, 0, TAU, 1, 0, C, 3, 1, 0, WORK, 1, 0, 3 );
* // returns 0
* // C => <Float64Array>[ -1, -3, -5, 2, 4, 6 ]
*/
declare var dormbr: Routine;


// EXPORTS //

export = dormbr;
